 31→/// State for an active benchmark run provisioned via `setup`.
 32→struct RunState {
 33→    /// Spice Cloud app ID.
 34→    app_id: i64,
 35→    /// API key for the app (used for Flight SQL authentication).
 36→    api_key: String,
 37→    /// Flight SQL endpoint URL derived from the cname.
 38→    flight_url: String,
 39→    /// Cloud client used during provisioning (reused for teardown).
 40→    cloud: CloudClient,
 41→    /// Region cname (used to build the SQL endpoint URL).
 42→    cname: String,
 43→    /// Table names created for this run (for cleanup during teardown).
 44→    created_tables: Vec<String>,
 45→    /// ETL sink mode used by this run.
 46→    etl_sink_mode: EtlSinkMode,
 47→}
 48→
 49→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 50→enum EtlSinkMode {
 51→    Adbc,
 52→    IcebergObjectStore,
 53→}
 54→
 55→impl EtlSinkMode {
 56→    fn from_setup_metadata(metadata: &HashMap<String, serde_json::Value>) -> anyhow::Result<Self> {
 57→        let value = metadata
 58→            .get("etl_sink_mode")
 59→            .and_then(serde_json::Value::as_str)
 60→            .unwrap_or("adbc");
 61→
 62→        match value {
 63→            "adbc" => Ok(Self::Adbc),
 64→            "iceberg-object-store" => Ok(Self::IcebergObjectStore),
 65→            other => Err(anyhow::anyhow!(
 66→                "Unsupported setup metadata etl_sink_mode '{other}'. Allowed values: adbc, iceberg-object-store"
 67→            )),
 68→        }
 69→    }
 70→}
 71→
 72→#[derive(Debug, Clone)]
 73→struct SetupConfig {
 74→    etl_sink_mode: EtlSinkMode,
 75→    etl_region: Option<String>,
 76→    etl_endpoint: Option<String>,
 77→    etl_iceberg_warehouse_uri: Option<String>,
 78→    etl_iceberg_namespace: Option<String>,
 79→}
 80→
 81→impl SetupConfig {
 82→    fn from_metadata(metadata: &HashMap<String, serde_json::Value>) -> anyhow::Result<Self> {
 83→        Ok(Self {
 84→            etl_sink_mode: EtlSinkMode::from_setup_metadata(metadata)?,
 85→            etl_region: metadata_string(metadata, "etl_region"),
 86→            etl_endpoint: metadata_string(metadata, "etl_endpoint"),
 87→            etl_iceberg_warehouse_uri: metadata_string(metadata, "etl_iceberg_warehouse_uri"),
 88→            etl_iceberg_namespace: metadata_string(metadata, "etl_iceberg_namespace"),
 89→        })
 90→    }
 91→}
 92→
 93→fn metadata_string(metadata: &HashMap<String, serde_json::Value>, key: &str) -> Option<String> {
 94→    metadata
 95→        .get(key)
 96→        .and_then(serde_json::Value::as_str)
 97→        .map(str::trim)
 98→        .filter(|s| !s.is_empty())
 99→        .map(ToString::to_string)
100→}
101→
102→/// System adapter handler that provisions Spice Cloud apps.
103→struct SpidapterHandler {
104→    /// Active runs keyed by run ID.
105→    runs: HashMap<Uuid, RunState>,
106→    /// Spice Cloud API URL override (from CLI args).
107→    api_url_override: Option<String>,
108→    /// Timeout in seconds for deployment readiness.
109→    ready_wait: u64,
110→    /// Release channel for the spice.ai runtime image.
111→    channel: Option<String>,
112→}
113→
114→impl SpidapterHandler {
115→    fn new(args: &StdioArgs) -> Self {
116→        Self {
117→            runs: HashMap::new(),
118→            api_url_override: args.spice_cloud_api_url.clone(),
119→            ready_wait: args.ready_wait,
120→            channel: args.channel.clone(),
121→        }
122→    }
123→}
124→
125→#[async_trait]
126→impl Handler for SpidapterHandler {
127→    async fn setup(
128→        &mut self,
129→        run_id: Uuid,
130→        metadata: HashMap<String, serde_json::Value>,
131→    ) -> Result<SetupResponse, String> {
132→        eprintln!(
133→            "[stdio] setup: run_id={run_id}, metadata_keys={:?}",
134→            metadata.keys().collect::<Vec<_>>()
135→        );
136→
137→        let setup_config = SetupConfig::from_metadata(&metadata)
138→            .map_err(|e| format!("Invalid setup metadata: {e}"))?;
139→
140→        let state = provision_spice_cloud_app(
141→            run_id,
142→            self.api_url_override.as_deref(),
143→            self.ready_wait,
144→            self.channel.as_deref(),
145→            &setup_config,
146→        )
147→        .await
148→        .map_err(|e| format!("Setup failed: {e}"))?;
149→
150→        let response = SetupResponse {
151→            driver: AdbcDriver::Flightsql,
152→            db_kwargs: HashMap::from([
153→                (
154→                    "uri".to_string(),
155→                    serde_json::Value::String(state.flight_url.clone()),
156→                ),
157→                (
158→                    "username".to_string(),
159→                    serde_json::Value::String(String::new()),
160→                ),
161→                (
162→                    "password".to_string(),
163→                    serde_json::Value::String(state.api_key.clone()),
164→                ),
165→            ]),
166→        };
167→
168→        self.runs.insert(run_id, state);
169→        Ok(response)
170→    }
171→
172→    async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
173→        let state = self
174→            .runs
175→            .get(&run_id)
176→            .ok_or_else(|| format!("No active run found for {run_id}"))?;
177→
178→        let cloud_metrics = state
179→            .cloud
180→            .get_app_metrics(state.app_id)
181→            .await
182→            .map_err(|e| format!("Failed to fetch metrics: {e}"))?;
183→
184→        let pods = cloud_metrics.metrics.values().collect::<Vec<_>>();
185→
186→        let resource = if pods.is_empty() {
187→            ResourceMetrics::default()
188→        } else {
189→            let avg_cpu = match pods
190→                .iter()
191→                .filter_map(|p| p.cpu_usage_percent.is_some().then(|| 1.0))
192→                .sum::<f64>()
193→            {
194→                0.0 => None,
195→                n => Some(pods.iter().filter_map(|p| p.cpu_usage_percent).sum::<f64>() / n),
196→            };
197→
198→            let total_memory = match pods
199→                .iter()
200→                .filter_map(|p| p.memory_usage_bytes.is_some().then(|| 1))
201→                .sum::<u64>()
202→            {
203→                0 => None,
204→                n => Some(
205→                    pods.iter()
206→                        .filter_map(|p| p.memory_usage_bytes)
207→                        .sum::<u64>()
208→                        / n as u64,
209→                ),
210→            };
211→            ResourceMetrics {
212→                cpu_usage_percent: avg_cpu,
213→                memory_usage_bytes: total_memory,
214→                disk_read_bytes: None,
215→                disk_write_bytes: None,
216→                disk_read_iops: None,
217→                disk_write_iops: None,
218→            }
219→        };
220→
221→        let ingestion = cloud_metrics
222→            .ingestion
223→            .map(|i| IngestionMetrics {
224→                rows_ingested: i.rows_ingested,
225→                bytes_ingested: i.bytes_ingested,
226→                ..IngestionMetrics::default()
227→            })
228→            .unwrap_or_default();
229→
230→        Ok(MetricsResponse {
231→            resource,
232→            ingestion,
233→        })
234→    }
235→
236→    async fn create_tables(
237→        &mut self,
238→        run_id: Uuid,
239→        datasets: HashMap<String, DatasetConfig>,
240→    ) -> Result<CreateTablesResponse, String> {
241→        eprintln!("[stdio] create_tables: run_id={run_id}");
242→
243→        let state = self
244→            .runs
245→            .get_mut(&run_id)
246→            .ok_or_else(|| format!("Unknown run_id: {run_id}"))?;
247→
248→        let client = reqwest::Client::builder()
249→            .timeout(Duration::from_secs(60))
250→            .build()
251→            .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
252→
253→        let sql_url = sql_url_from_cname(&state.cname);
254→
255→        if state.etl_sink_mode == EtlSinkMode::IcebergObjectStore {
256→            eprintln!(
257→                "[stdio] create_tables: skipping SQL DDL for run_id={run_id} (etl_sink_mode=iceberg-object-store)"
258→            );
259→            return Ok(CreateTablesResponse { ok: true });
260→        }
261→
262→        for (table_name, config) in &datasets {
263→            let ddl = create_table_ddl(table_name, config);
264→            eprintln!("[stdio] create_tables: executing DDL: {ddl}");
265→
266→            let response = client
267→                .post(&sql_url)
268→                .header("X-API-Key", &state.api_key)
269→                .body(ddl.clone())
270→                .send()
271→                .await
272→                .map_err(|e| format!("Failed to send DDL for table '{table_name}': {e}"))?;
273→
274→            if !response.status().is_success() {
275→                let status = response.status();
276→                let body = response
277→                    .text()
278→                    .await
279→                    .unwrap_or_else(|_| "<failed to read body>".to_string());
280→                return Err(format!(
281→                    "DDL for table '{table_name}' failed ({status}): {body}"
282→                ));
283→            }
284→
285→            state.created_tables.push(table_name.clone());
286→            eprintln!("[stdio] create_tables: table '{table_name}' created");
287→        }
288→        Ok(CreateTablesResponse { ok: true })
289→    }
290→
291→    async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
292→        eprintln!("[stdio] teardown: run_id={run_id}");
293→
294→        let Some(state) = self.runs.remove(&run_id) else {
295→            eprintln!("[stdio] teardown: run_id={run_id} not found (already torn down?)");
296→            return Ok(TeardownResponse { ok: true });
297→        };
298→
299→        // Drop tables via DDL before deleting the app
300→        if !state.created_tables.is_empty() {
301→            let client = reqwest::Client::builder()
302→                .timeout(Duration::from_secs(30))
303→                .build()
304→                .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
305→
306→            let sql_url = sql_url_from_cname(&state.cname);
307→
308→            for table_name in &state.created_tables {
309→                let ddl = format!("DROP TABLE IF EXISTS {}", quote_ident(table_name));
310→                eprintln!("[stdio] teardown: executing DDL: {ddl}");
311→
312→                match client
313→                    .post(&sql_url)
314→                    .header("X-API-Key", &state.api_key)
315→                    .body(ddl)
316→                    .send()
317→                    .await
318→                {
319→                    Ok(response) if response.status().is_success() => {
320→                        eprintln!("[stdio] teardown: table '{table_name}' dropped");
321→                    }
322→                    Ok(response) => {
323→                        let status = response.status();
324→                        let body = response
325→                            .text()
326→                            .await
327→                            .unwrap_or_else(|_| "<failed to read body>".to_string());
328→                        eprintln!(
329→                            "[stdio] teardown: failed to drop table '{table_name}' ({status}): {body}"
330→                        );
331→                    }
332→                    Err(e) => {
333→                        eprintln!("[stdio] teardown: failed to drop table '{table_name}': {e}");
334→                    }
335→                }
336→            }
337→        }
338→
339→        eprintln!(
340→            "[stdio] teardown: deleting app {} at {}",
341→            state.app_id,
342→            state.cloud.base_url()
343→        );
344→
345→        commands::delete_app(&state.cloud, state.app_id)
346→            .await
347→            .map_err(|e| format!("Failed to delete app {}: {e}", state.app_id))?;
348→
349→        eprintln!("[stdio] teardown: app {} deleted", state.app_id);
350→        Ok(TeardownResponse { ok: true })
351→    }
352→}
