354→pub async fn run_stdio_server(args: &StdioArgs) -> anyhow::Result<()> {
355→    let handler = SpidapterHandler::new(args);
356→    let mut server = Server::new(handler);
357→    server
358→        .run_stdio()
359→        .await
360→        .map_err(|e| anyhow::anyhow!("Stdio server error: {e}"))
361→}
