363→// ── Spice Cloud provisioning ─────────────────────────────────────────
364→
365→/// Provision a Spice Cloud app from the setup request.
366→///
367→/// Follows the same flow as `SpiceCloudSpicedStarter::start()`:
368→/// 1. Resolve the default cname / region
369→/// 2. Create or find the SCP app
370→/// 3. Generate and upload the spicepod from the dataset configs
371→/// 4. Set secrets (RUNNER + any env-based secrets)
372→/// 5. Create a deployment
373→/// 6. Wait for the deployment to become ready
374→async fn provision_spice_cloud_app(
375→    run_id: Uuid,
376→    api_url_override: Option<&str>,
377→    ready_wait: u64,
378→    channel: Option<&str>,
379→    setup_config: &SetupConfig,
380→) -> anyhow::Result<RunState> {
381→    let cloud = commands::build_cloud_client(api_url_override)?;
382→
383→    let cname = commands::resolve_default_cname(&cloud).await?;
384→    let flight_url = commands::flight_url_from_cname(&cname);
385→    let run_id_str = run_id.to_string();
386→    let short_id = run_id_str.split('-').next().unwrap_or_default();
387→    let app_name = commands::sanitize_app_name(&format!("spidapter-{short_id}"));
388→
389→    eprintln!("[stdio] Spice Cloud API: {}", cloud.base_url());
390→    eprintln!("[stdio] Region cname: {cname}");
391→    eprintln!("[stdio] Flight endpoint: {flight_url}");
392→    eprintln!("[stdio] App name: {app_name}");
393→
394→    let (app_id, app_api_key) = commands::ensure_spice_cloud_app(&cloud, &app_name).await?;
395→
396→    let api_key = app_api_key.ok_or_else(|| {
397→        anyhow::anyhow!("Spice Cloud did not return an API key for app '{app_name}'")
398→    })?;
399→
400→    eprintln!("[stdio] App ID: {app_id}");
401→
402→    // Generate initial spicepod YAML (tables created later via create_tables)
403→    let spicepod_yaml = generate_initial_spicepod(&run_id, setup_config)?;
404→    eprintln!("[stdio] Generated spicepod:\n{spicepod_yaml}");
405→
406→    eprintln!("[stdio] Uploading spicepod to app...");
407→    commands::apply_spicepod_to_app(&cloud, app_id, &spicepod_yaml).await?;
408→    eprintln!("[stdio] Spicepod uploaded");
409→
410→    // Set secrets from environment for any secret references in the spicepod
411→    eprintln!("[stdio] Setting secrets from spicepod...");
412→    commands::secrets::set_spicepod_secrets(&cloud, app_id, &spicepod_yaml).await?;
413→    eprintln!("[stdio] Spicepod secrets set");
414→
415→    eprintln!("[stdio] Setting RUNNER secret...");
416→    commands::secrets::set_secret(&cloud, app_id, "RUNNER", "spidapter").await?;
417→    eprintln!("[stdio] RUNNER secret set");
418→
419→    eprintln!("[stdio] Creating deployment...");
420→    commands::create_deployment(&cloud, app_id, channel).await?;
421→
422→    let poll_client = reqwest::Client::builder()
423→        .timeout(Duration::from_secs(600))
424→        .build()?;
425→    commands::wait_for_deployment_ready(
426→        &poll_client,
427→        &cname,
428→        &api_key,
429→        Duration::from_secs(ready_wait),
430→    )
431→    .await?;
432→
433→    eprintln!("[stdio] Spice Cloud deployment ready for app '{app_name}' at {flight_url}");
434→
435→    Ok(RunState {
436→        app_id,
437→        api_key,
438→        flight_url,
439→        cloud,
440→        cname,
441→        created_tables: Vec::new(),
442→        etl_sink_mode: setup_config.etl_sink_mode,
443→    })
444→}
445→
446→/// Build the SQL endpoint URL from a Spice Cloud cname.
447→fn sql_url_from_cname(cname: &str) -> String {
448→    format!("https://{cname}.spiceai.io/v1/sql")
449→}
450→
451→/// Generate a `CREATE TABLE IF NOT EXISTS` DDL statement from a dataset's Arrow schema,
452→/// with acceleration configured for the cayenne engine with append refresh every 10 seconds.
453→///
454→/// If the schema contains a timestamp column, it is used as the acceleration time column
455→/// with `timestamptz` format.
456→fn create_table_ddl(table_name: &str, config: &DatasetConfig) -> String {
457→    let columns: Vec<String> = config
458→        .schema
459→        .fields()
460→        .iter()
461→        .map(|f| {
462→            let sql_type = sql_type_for_arrow(f.data_type());
463→            let nullable = if f.is_nullable() { "" } else { " NOT NULL" };
464→            format!("{} {sql_type}{nullable}", quote_ident(f.name()))
465→        })
466→        .collect();
467→
468→    let with_opts = [
469→        "\"acceleration.engine\" = 'cayenne'".to_string(),
470→        "\"acceleration.mode\" = 'file'".to_string(),
471→        "\"acceleration.refresh_mode\" = 'full'".to_string(),
472→        "\"acceleration.refresh_check_interval\" = '1s'".to_string(),
473→    ];
474→
475→    format!(
476→        "CREATE TABLE IF NOT EXISTS {} ({}) WITH ({})",
477→        quote_ident(table_name),
478→        columns.join(", "),
479→        with_opts.join(", ")
480→    )
481→}
482→
483→/// Map Arrow data types to SQL type names for DDL.
484→fn sql_type_for_arrow(data_type: &DataType) -> String {
485→    match data_type {
486→        DataType::Boolean => "BOOLEAN".to_string(),
487→        DataType::Int8 => "TINYINT".to_string(),
488→        DataType::UInt8 | DataType::Int16 => "SMALLINT".to_string(),
489→        DataType::UInt16 | DataType::Int32 => "INT".to_string(),
490→        DataType::UInt32 | DataType::Int64 => "BIGINT".to_string(),
491→        DataType::UInt64 => "DECIMAL(20, 0)".to_string(),
492→        DataType::Float32 => "FLOAT".to_string(),
493→        DataType::Float64 => "DOUBLE".to_string(),
494→        DataType::Date32 | DataType::Date64 => "DATE".to_string(),
495→        DataType::Timestamp(
496→            TimeUnit::Second | TimeUnit::Millisecond | TimeUnit::Microsecond | TimeUnit::Nanosecond,
497→            _,
498→        ) => "TIMESTAMP".to_string(),
499→        DataType::Decimal128(p, s) => format!("DECIMAL({p}, {s})"),
500→        DataType::Binary | DataType::LargeBinary => "BINARY".to_string(),
501→        _ => "VARCHAR".to_string(),
502→    }
503→}
504→
505→fn quote_ident(ident: &str) -> String {
506→    format!("\"{}\"", ident.replace('"', "\"\""))
507→}
508→
509→/// Generate the initial spicepod YAML with an Iceberg Glue catalog as the default catalog.
510→fn generate_initial_spicepod(run_id: &Uuid, setup_config: &SetupConfig) -> anyhow::Result<String> {
511→    let run_id_str = run_id.to_string();
512→    let short_id = run_id_str.split('-').next().unwrap_or_default();
513→    let region = setup_config
514→        .etl_region
515→        .clone()
516→        .or_else(|| std::env::var("SPIDAPTER_ICEBERG_REGION").ok())
517→        .or_else(|| std::env::var("AWS_REGION").ok())
518→        .or_else(|| std::env::var("AWS_DEFAULT_REGION").ok())
519→        .unwrap_or_else(|| "us-east-1".to_string());
520→
521→    match setup_config.etl_sink_mode {
522→        EtlSinkMode::IcebergObjectStore => {
523→            let warehouse_uri = setup_config
524→                .etl_iceberg_warehouse_uri
525→                .as_deref()
526→                .ok_or_else(|| {
527→                    anyhow::anyhow!(
528→                        "Missing setup metadata etl_iceberg_warehouse_uri for etl_sink_mode=iceberg-object-store"
529→                    )
530→                })?;
531→
532→            let mut params = vec![
533→                "      iceberg_s3_access_key_id: ${secrets:AWS_ACCESS_KEY_ID}".to_string(),
534→                "      iceberg_s3_secret_access_key: ${secrets:AWS_SECRET_ACCESS_KEY}".to_string(),
535→                format!("      iceberg_s3_region: {region}"),
536→            ];
537→
538→            if let Some(endpoint) = setup_config
539→                .etl_endpoint
540→                .clone()
541→                .or_else(|| std::env::var("SPIDAPTER_ICEBERG_S3_ENDPOINT").ok())
542→            {
543→                params.push(format!("      iceberg_s3_endpoint: {endpoint}"));
544→            }
545→
546→            if let Some(namespace) = &setup_config.etl_iceberg_namespace {
547→                eprintln!(
548→                    "[stdio] setup: iceberg object-store namespace from metadata: {namespace}"
549→                );
550→            }
551→
552→            Ok(format!(
553→                "version: v1beta1
554→kind: Spicepod
555→name: spidapter-{short_id}
556→
557→catalogs:
558→  - from: iceberg:{warehouse_uri}
559→    name: spice
560→    access: read
561→    params:
562→{}
563→",
564→                params.join("\n")
565→            ))
566→        }
567→        EtlSinkMode::Adbc => {
568→            let catalog_from = if let Ok(from) = std::env::var("SPIDAPTER_ICEBERG_CATALOG_FROM") {
569→                from
570→            } else {
571→                let account_id = std::env::var("SPIDAPTER_ICEBERG_CATALOG_ACCOUNT_ID")
572→                    .or_else(|_| std::env::var("AWS_ICEBERG_ACCOUNT_ID"))
573→                    .map_err(|_| {
574→                        anyhow::anyhow!(
575→                            "Missing Iceberg catalog account id. Set SPIDAPTER_ICEBERG_CATALOG_FROM or SPIDAPTER_ICEBERG_CATALOG_ACCOUNT_ID (or AWS_ICEBERG_ACCOUNT_ID)."
576→                        )
577→                    })?;
578→
579→                format!(
580→                    "iceberg:https://glue.{region}.amazonaws.com/iceberg/v1/catalogs/{account_id}/namespaces"
581→                )
582→            };
583→
584→            Ok(format!(
585→                "version: v1beta1
586→kind: Spicepod
587→name: spidapter-{short_id}
588→
589→runtime:
590→  scheduler:
591→    state_location: s3://spicebench-ap-northeast-3/spidapter-{short_id}/
592→    params:
593→      s3_auth: key
