182→            .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
183→
184→        let sql_url = sql_url_from_cname(&state.cname);
185→
186→        if state.etl_sink_mode != EtlSinkMode::IcebergObjectStore {
187→            for (table_name, config) in &datasets {
188→                let ddl = create_table_ddl(table_name, config);
189→                eprintln!("[stdio] setup: executing DDL: {ddl}");
190→
191→                let resp = client
192→                    .post(&sql_url)
193→                    .header("X-API-Key", &state.api_key)
194→                    .body(ddl.clone())
195→                    .send()
196→                    .await
197→                    .map_err(|e| format!("Failed to send DDL for table '{table_name}': {e}"))?;
198→
199→                let status = resp.status();
200→                if !status.is_success() {
201→                    let body = resp
202→                        .text()
203→                        .await
204→                        .unwrap_or_else(|_| "<failed to read body>".to_string());
205→                    return Err(format!(
206→                        "DDL for table '{table_name}' failed ({status}): {body}"
207→                    ));
208→                }
209→
210→                state.created_tables.push(table_name.clone());
211→                eprintln!("[stdio] setup: table '{table_name}' created");
212→            }
213→        } else {
214→            eprintln!(
215→                "[stdio] setup: skipping SQL DDL for run_id={run_id} (etl_sink_mode=iceberg-object-store)"
216→            );
217→        }
218→
219→        Ok(response)
220→    }
221→
222→    async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
223→        let state = self
224→            .runs
225→            .get(&run_id)
226→            .ok_or_else(|| format!("No active run found for {run_id}"))?;
227→
228→        let cloud_metrics = state
229→            .cloud
230→            .get_app_metrics(state.app_id)
231→            .await
232→            .map_err(|e| format!("Failed to fetch metrics: {e}"))?;
233→
234→        let pods = cloud_metrics.metrics.values().collect::<Vec<_>>();
235→
236→        let resource = if pods.is_empty() {
237→            ResourceMetrics::default()
238→        } else {
239→            let avg_cpu = match pods
240→                .iter()
241→                .filter_map(|p| p.cpu_usage_percent.is_some().then(|| 1.0))
242→                .sum::<f64>()
243→            {
244→                0.0 => None,
245→                n => Some(pods.iter().filter_map(|p| p.cpu_usage_percent).sum::<f64>() / n),
246→            };
247→
248→            let total_memory = match pods
249→                .iter()
250→                .filter_map(|p| p.memory_usage_bytes.is_some().then(|| 1))
251→                .sum::<u64>()
252→            {
253→                0 => None,
254→                n => Some(
255→                    pods.iter()
256→                        .filter_map(|p| p.memory_usage_bytes)
257→                        .sum::<u64>()
258→                        / n as u64,
259→                ),
260→            };
261→            ResourceMetrics {
262→                cpu_usage_percent: avg_cpu,
263→                memory_usage_bytes: total_memory,
264→                disk_read_bytes: None,
265→                disk_write_bytes: None,
266→                disk_read_iops: None,
267→                disk_write_iops: None,
268→            }
269→        };
270→
271→        let ingestion = cloud_metrics
272→            .ingestion
273→            .map(|i| IngestionMetrics {
274→                rows_ingested: i.rows_ingested,
275→                bytes_ingested: i.bytes_ingested,
276→                ..IngestionMetrics::default()
277→            })
278→            .unwrap_or_default();
279→
280→        Ok(MetricsResponse {
281→            resource,
282→            ingestion,
283→        })
284→    }
285→
286→    async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
287→        eprintln!("[stdio] teardown: run_id={run_id}");
288→
289→        let Some(state) = self.runs.remove(&run_id) else {
290→            eprintln!("[stdio] teardown: run_id={run_id} not found (already torn down?)");
291→            return Ok(TeardownResponse { ok: true });
292→        };
293→
294→        // Drop tables via DDL before deleting the app
295→        if !state.created_tables.is_empty() {
296→            let client = reqwest::Client::builder()
297→                .timeout(Duration::from_secs(30))
298→                .build()
299→                .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
300→
301→            let sql_url = sql_url_from_cname(&state.cname);
302→
303→            for table_name in &state.created_tables {
304→                let ddl = format!("DROP TABLE IF EXISTS {}", quote_ident(table_name));
305→                eprintln!("[stdio] teardown: executing DDL: {ddl}");
306→
307→                match client
308→                    .post(&sql_url)
309→                    .header("X-API-Key", &state.api_key)
310→                    .body(ddl)
311→                    .send()
312→                    .await
313→                {
314→                    Ok(response) if response.status().is_success() => {
315→                        eprintln!("[stdio] teardown: table '{table_name}' dropped");
316→                    }
317→                    Ok(response) => {
318→                        let status = response.status();
319→                        let body = response
320→                            .text()
321→                            .await
322→                            .unwrap_or_else(|_| "<failed to read body>".to_string());
323→                        eprintln!(
324→                            "[stdio] teardown: failed to drop table '{table_name}' ({status}): {body}"
325→                        );
326→                    }
327→                    Err(e) => {
328→                        eprintln!("[stdio] teardown: failed to drop table '{table_name}': {e}");
329→                    }
330→                }
331→            }
332→        }
333→
334→        eprintln!(
335→            "[stdio] teardown: deleting app {} at {}",
336→            state.app_id,
337→            state.cloud.base_url()
338→        );
339→
340→        commands::delete_app(&state.cloud, state.app_id)
341→            .await
342→            .map_err(|e| format!("Failed to delete app {}: {e}", state.app_id))?;
343→
344→        eprintln!("[stdio] teardown: app {} deleted", state.app_id);
345→        Ok(TeardownResponse { ok: true })
346→    }
347→}
