358→// ── Spice Cloud provisioning ─────────────────────────────────────────
359→
360→/// Provision a Spice Cloud app from the setup request.
361→///
362→/// Follows the same flow as `SpiceCloudSpicedStarter::start()`:
363→/// 1. Resolve the default cname / region
364→/// 2. Create or find the SCP app
365→/// 3. Generate and upload the spicepod from the dataset configs
366→/// 4. Set secrets (RUNNER + any env-based secrets)
367→/// 5. Create a deployment
368→/// 6. Wait for the deployment to become ready
369→async fn provision_spice_cloud_app(
370→    run_id: Uuid,
371→    api_url_override: Option<&str>,
372→    ready_wait: u64,
373→    channel: Option<&str>,
374→    setup_config: &SetupConfig,
375→) -> anyhow::Result<RunState> {
376→    let cloud = commands::build_cloud_client(api_url_override)?;
377→
378→    let cname = commands::resolve_default_cname(&cloud).await?;
379→    let flight_url = commands::flight_url_from_cname(&cname);
380→    let run_id_str = run_id.to_string();
381→    let short_id = run_id_str.split('-').next().unwrap_or_default();
382→    let app_name = commands::sanitize_app_name(&format!("spidapter-{short_id}"));
383→
384→    eprintln!("[stdio] Spice Cloud API: {}", cloud.base_url());
385→    eprintln!("[stdio] Region cname: {cname}");
386→    eprintln!("[stdio] Flight endpoint: {flight_url}");
387→    eprintln!("[stdio] App name: {app_name}");
388→
389→    let (app_id, app_api_key) = commands::ensure_spice_cloud_app(&cloud, &app_name).await?;
390→
391→    let api_key = app_api_key.ok_or_else(|| {
392→        anyhow::anyhow!("Spice Cloud did not return an API key for app '{app_name}'")
393→    })?;
394→
395→    eprintln!("[stdio] App ID: {app_id}");
396→
397→    // Generate initial spicepod YAML (tables created later via create_tables)
398→    let spicepod_yaml = generate_initial_spicepod(&run_id, setup_config)?;
399→    eprintln!("[stdio] Generated spicepod:\n{spicepod_yaml}");
400→
401→    eprintln!("[stdio] Uploading spicepod to app...");
402→    commands::apply_spicepod_to_app(&cloud, app_id, &spicepod_yaml).await?;
403→    eprintln!("[stdio] Spicepod uploaded");
404→
405→    // Set secrets from environment for any secret references in the spicepod
406→    eprintln!("[stdio] Setting secrets from spicepod...");
407→    commands::secrets::set_spicepod_secrets(&cloud, app_id, &spicepod_yaml).await?;
408→    eprintln!("[stdio] Spicepod secrets set");
409→
410→    eprintln!("[stdio] Setting RUNNER secret...");
411→    commands::secrets::set_secret(&cloud, app_id, "RUNNER", "spidapter").await?;
412→    eprintln!("[stdio] RUNNER secret set");
413→
414→    eprintln!("[stdio] Creating deployment...");
415→    commands::create_deployment(&cloud, app_id, channel).await?;
416→
417→    let poll_client = reqwest::Client::builder()
418→        .timeout(Duration::from_secs(600))
419→        .build()?;
420→    commands::wait_for_deployment_ready(
421→        &poll_client,
422→        &cname,
423→        &api_key,
424→        Duration::from_secs(ready_wait),
425→    )
426→    .await?;
427→
428→    eprintln!("[stdio] Spice Cloud deployment ready for app '{app_name}' at {flight_url}");
429→
430→    Ok(RunState {
431→        app_id,
432→        api_key,
433→        flight_url,
434→        cloud,
435→        cname,
436→        created_tables: Vec::new(),
437→        etl_sink_mode: setup_config.etl_sink_mode,
438→    })
439→}
