441→/// Build the SQL endpoint URL from a Spice Cloud cname.
442→fn sql_url_from_cname(cname: &str) -> String {
443→    format!("https://{cname}.spiceai.io/v1/sql")
444→}
445→
446→/// Generate a `CREATE TABLE IF NOT EXISTS` DDL statement from a dataset's Arrow schema,
447→/// with acceleration configured for the cayenne engine with append refresh every 10 seconds.
448→///
449→/// If the schema contains a timestamp column, it is used as the acceleration time column
450→/// with `timestamptz` format.
451→fn create_table_ddl(table_name: &str, config: &DatasetConfig) -> String {
452→    let columns: Vec<String> = config
453→        .schema
454→        .fields()
455→        .iter()
456→        .map(|f| {
457→            let sql_type = sql_type_for_arrow(f.data_type());
458→            let nullable = if f.is_nullable() { "" } else { " NOT NULL" };
459→            format!("{} {sql_type}{nullable}", quote_ident(f.name()))
460→        })
461→        .collect();
462→
463→    let with_opts = [
464→        "\"acceleration.engine\" = 'cayenne'".to_string(),
465→        "\"acceleration.mode\" = 'file'".to_string(),
466→        "\"acceleration.refresh_mode\" = 'full'".to_string(),
467→        "\"acceleration.refresh_check_interval\" = '1s'".to_string(),
468→    ];
469→
470→    format!(
471→        "CREATE TABLE IF NOT EXISTS {} ({}) WITH ({})",
472→        quote_ident(table_name),
473→        columns.join(", "),
474→        with_opts.join(", ")
475→    )
476→}
477→
478→/// Map Arrow data types to SQL type names for DDL.
479→fn sql_type_for_arrow(data_type: &DataType) -> String {
480→    match data_type {
481→        DataType::Boolean => "BOOLEAN".to_string(),
482→        DataType::Int8 => "TINYINT".to_string(),
483→        DataType::UInt8 | DataType::Int16 => "SMALLINT".to_string(),
484→        DataType::UInt16 | DataType::Int32 => "INT".to_string(),
485→        DataType::UInt32 | DataType::Int64 => "BIGINT".to_string(),
486→        DataType::UInt64 => "DECIMAL(20, 0)".to_string(),
487→        DataType::Float32 => "FLOAT".to_string(),
488→        DataType::Float64 => "DOUBLE".to_string(),
489→        DataType::Date32 | DataType::Date64 => "DATE".to_string(),
490→        DataType::Timestamp(
491→            TimeUnit::Second | TimeUnit::Millisecond | TimeUnit::Microsecond | TimeUnit::Nanosecond,
492→            _,
493→        ) => "TIMESTAMP".to_string(),
494→        DataType::Decimal128(p, s) => format!("DECIMAL({p}, {s})"),
495→        DataType::Binary | DataType::LargeBinary => "BINARY".to_string(),
496→        _ => "VARCHAR".to_string(),
497→    }
498→}
499→
500→fn quote_ident(ident: &str) -> String {
501→    format!("\"{}\"", ident.replace('"', "\"\""))
502→}
503→
504→/// Generate the initial spicepod YAML with an Iceberg Glue catalog as the default catalog.
505→fn generate_initial_spicepod(run_id: &Uuid, setup_config: &SetupConfig) -> anyhow::Result<String> {
506→    let run_id_str = run_id.to_string();
507→    let short_id = run_id_str.split('-').next().unwrap_or_default();
508→    let region = setup_config
509→        .etl_region
510→        .clone()
511→        .or_else(|| std::env::var("SPIDAPTER_ICEBERG_REGION").ok())
512→        .or_else(|| std::env::var("AWS_REGION").ok())
513→        .or_else(|| std::env::var("AWS_DEFAULT_REGION").ok())
514→        .unwrap_or_else(|| "us-east-1".to_string());
515→
516→    match setup_config.etl_sink_mode {
517→        EtlSinkMode::IcebergObjectStore => {
518→            let warehouse_uri = setup_config
519→                .etl_iceberg_warehouse_uri
520→                .as_deref()
521→                .ok_or_else(|| {
522→                    anyhow::anyhow!(
523→                        "Missing setup metadata etl_iceberg_warehouse_uri for etl_sink_mode=iceberg-object-store"
524→                    )
525→                })?;
526→
527→            let mut params = vec![
528→                "      iceberg_s3_access_key_id: ${secrets:AWS_ACCESS_KEY_ID}".to_string(),
529→                "      iceberg_s3_secret_access_key: ${secrets:AWS_SECRET_ACCESS_KEY}".to_string(),
530→                format!("      iceberg_s3_region: {region}"),
531→            ];
532→
533→            if let Some(endpoint) = setup_config
534→                .etl_endpoint
535→                .clone()
536→                .or_else(|| std::env::var("SPIDAPTER_ICEBERG_S3_ENDPOINT").ok())
537→            {
538→                params.push(format!("      iceberg_s3_endpoint: {endpoint}"));
539→            }
540→
541→            if let Some(namespace) = &setup_config.etl_iceberg_namespace {
542→                eprintln!(
543→                    "[stdio] setup: iceberg object-store namespace from metadata: {namespace}"
544→                );
545→            }
546→
547→            Ok(format!(
548→                "version: v1beta1
549→kind: Spicepod
550→name: spidapter-{short_id}
551→
552→catalogs:
553→  - from: iceberg:{warehouse_uri}
554→    name: spice
555→    access: read
556→    params:
557→{}
558→",
559→                params.join("\n")
560→            ))
561→        }
562→        EtlSinkMode::Adbc => {
563→            let catalog_from = if let Ok(from) = std::env::var("SPIDAPTER_ICEBERG_CATALOG_FROM") {
564→                from
565→            } else {
566→                let account_id = std::env::var("SPIDAPTER_ICEBERG_CATALOG_ACCOUNT_ID")
567→                    .or_else(|_| std::env::var("AWS_ICEBERG_ACCOUNT_ID"))
568→                    .map_err(|_| {
569→                        anyhow::anyhow!(
570→                            "Missing Iceberg catalog account id. Set SPIDAPTER_ICEBERG_CATALOG_FROM or SPIDAPTER_ICEBERG_CATALOG_ACCOUNT_ID (or AWS_ICEBERG_ACCOUNT_ID)."
571→                        )
572→                    })?;
573→
574→                format!(
575→                    "iceberg:https://glue.{region}.amazonaws.com/iceberg/v1/catalogs/{account_id}/namespaces"
576→                )
577→            };
578→
579→            Ok(format!(
580→                "version: v1beta1
581→kind: Spicepod
582→name: spidapter-{short_id}
583→
584→runtime:
585→  scheduler:
586→    state_location: s3://spicebench-ap-northeast-3/spidapter-{short_id}/
587→    params:
588→      s3_auth: key
589→      s3_key: ${{secrets:AWS_ACCESS_KEY_ID}}
590→      s3_secret: ${{secrets:AWS_SECRET_ACCESS_KEY}}
591→      s3_session_token: ${{secrets:AWS_SESSION_TOKEN}}
592→      s3_region: ap-northeast-3
593→
594→
595→catalogs:
596→  - from: {catalog_from}
597→    name: spice
598→    access: read_write_create
599→    params:
600→      iceberg_sigv4_enabled: true
601→      iceberg_s3_access_key_id: ${{secrets:AWS_ACCESS_KEY_ID}}
602→      iceberg_s3_secret_access_key: ${{secrets:AWS_SECRET_ACCESS_KEY}}
603→      iceberg_s3_region: {region}
604→"
605→            ))
606→        }
607→    }
608→}
