                        )
                    })?;

                format!(
                    "iceberg:https://glue.{region}.amazonaws.com/iceberg/v1/catalogs/{account_id}/namespaces"
                )
            };

            Ok(format!(
                "version: v1beta1
kind: Spicepod
name: spidapter-{short_id}

runtime:
  scheduler:
    state_location: s3://spicebench-ap-northeast-3/spidapter-{short_id}/
    params:
