            "unexpected error: {err}"
        );
    }

    #[test]
    fn setup_config_parses_s3_base_path() {
        let metadata = HashMap::from([(
            "etl_s3_base_path".to_string(),
            serde_json::Value::String("my-bucket/prefix".to_string()),
        )]);

        let config = SetupConfig::from_metadata(&metadata).expect("metadata should parse");
        assert_eq!(config.etl_s3_base_path, "my-bucket/prefix");
    }

    #[test]
    fn generate_spicepod_includes_dataset_entries() {
        let setup_config = SetupConfig {
            etl_s3_base_path: "my-bucket/prefix".to_string(),
            etl_region: Some("us-west-2".to_string()),
            etl_endpoint: Some("http://localhost:9000".to_string()),
        };

        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let datasets = HashMap::from([(
            "my_table".to_string(),
            DatasetConfig {
                schema: schema.clone(),
            },
        )]);

